#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int data; struct Node *next; } Node;

Node *detect(Node *head) {
    Node *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            Node *p = head;
            while (p != slow) { p = p->next; slow = slow->next; }
            return p;
        }
    }
    return NULL;
}

int main(void) {
    /* 构造 1->2->3->4->5->6，并使 6 指回 3（环入口 data=3） */
    Node nodes[6];
    for (int i = 0; i < 6; i++) { nodes[i].data = i + 1; nodes[i].next = &nodes[i+1]; }
    nodes[5].next = &nodes[2];                     /* 成环，入口是 3 */

    Node *entry = detect(&nodes[0]);
    printf("环入口节点的值 = %d\n", entry ? entry->data : -1);
    printf("推导：2(a+b) = a+b+kc  =>  a = kc - b，故两指针必在入口相遇\n");
    return 0;
}
